return items.map(item => {
  const d = item.json;
  const textSent = d.followup_type === 'text'
    ? (d.text_template || '').replace(/{{name}}/g, d.display_name || '')
    : '[flow: ' + (d.followup_flow_ns || '') + '] — ' + (d.followup_description || '');
  const chatMemoryText = '[SEGUIMIENTO AUTOMÁTICO #' + d.next_sequence_number + '] ' + textSent;
  return { json: { ...d, textSent, chatMemoryText } };
});

const item = $input.item.json;
  const displayName = item.display_name ?? 'amig@';
  const rawMessages = Array.isArray(item.followup_messages) ? item.followup_messages : [];

  const mcMessages = rawMessages
    .sort((a, b) => a.sort_order - b.sort_order)
    .map((m) => {
      if (m.message_type === 'image') return { type: 'image', url: m.media_url };
      const text = (m.text_content ?? '').replace(/\{\{name\}\}/g, displayName);
      return { type: 'text', text };
    });

  const textSent = rawMessages
    .filter(m => m.message_type === 'text')
    .map(m => (m.text_content ?? '').replace(/\{\{name\}\}/g, displayName))
    .join(' | ');

  return [{ json: { ...item, mcMessages, textSent } }];

const pd = $('Loop Over Leads').first().json;
const esc = s => String(s || '').replace(/'/g, "''");
const stageId = pd.current_stage_id ? "'" + pd.current_stage_id + "'" : 'NULL';
const templateId = pd.template_id ? "'" + pd.template_id + "'" : 'NULL';
const delayMinutes = pd.next_delay_minutes;

const logSql = "INSERT INTO api.lead_followup_log (tenant_id, subscriber_id, conversation_id, stage_id, template_id, sequence_number, text_sent, status) VALUES ('" + pd.tenant_id + "','" + pd.subscriber_id + "','" + pd.conversation_id + "'," + stageId + "," + templateId + "," + pd.next_sequence_number + ",'" + esc(pd.textSent) + "','sent')";

const histSql = "INSERT INTO n8n_chat_histories (session_id, message) VALUES ('" + pd.manychat_subscriber_id + "', jsonb_build_object('type','ai','data',jsonb_build_object('content','" + esc(pd.chatMemoryText) + "','additional_kwargs','{}'))::jsonb)";

const updateSql = delayMinutes
  ? "UPDATE api.lead_crons SET next_sequence_number = next_sequence_number + 1, next_followup_at = NOW() + INTERVAL '" + parseInt(delayMinutes) + " minutes', is_active = TRUE, archived_at = NULL, archive_reason = NULL, updated_at = NOW() WHERE id = '" + pd.cron_id + "'"
  : "UPDATE api.lead_crons SET is_active = FALSE, archived_at = NOW(), archive_reason = 'max_followups', updated_at = NOW() WHERE id = '" + pd.cron_id + "'";


return [{ json: { logSql, histSql, updateSql } }];

const lead = $('Loop Over Leads').first().json;
  const buildSqlOutput = $('Build SQL').first().json;
  let textoParaMemoria;

  if (lead.followup_type === 'text') {
    textoParaMemoria = (lead.text_template ?? '').replace(/\{\{name\}\}/g, lead.display_name ?? '');
  } else if (lead.followup_type === 'flow') {
    textoParaMemoria = '[flow: ' + (lead.followup_flow_ns ?? '') + '] — ' + (lead.followup_description ?? '');
  } else if (lead.followup_type === 'content') {
    const imagePart = lead.image_context
      ? '[IMAGEN ENVIADA: ' + lead.image_context + '] '
      : '[IMAGEN ENVIADA] ';
    const textPart = (lead.content_text ?? '').replace(/\{\{name\}\}/g, lead.display_name ?? '');
    textoParaMemoria = (imagePart + textPart).trim();
  } else {
    textoParaMemoria = lead.followup_description ?? '';
  }

  const contenidoMemoria = '[SEGUIMIENTO AUTOMÁTICO #' + lead.next_sequence_number + '] ' + textoParaMemoria;

  return [{ json: {
    manychat_subscriber_id: lead.manychat_subscriber_id,
    contenidoMemoria,
    updateSql: buildSqlOutput.updateSql
  } }];

